t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def solve(a, S):
    th,tw=len(a),len(a[0]); cnt=collections.Counter(v for r in a for v in r); bgc=max(cnt,key=lambda k:(cnt[k],k))
    others=sorted([k for k in cnt if k!=bgc],key=lambda k:-cnt[k])
    dotcol=others[1]; obj=others[0]
    cells=[(y,x) for y in range(th) for x in range(tw) if a[y][x]==obj]
    y0=min(y for y,x in cells); x0=min(x for y,x in cells)
    y1=max(y for y,x in cells); x1=max(x for y,x in cells)
    Hb=y1-y0+1; Wb=x1-x0+1
    assert Hb%S==0 and Wb%S==0
    out=[]
    for i in range(Hb//S):
        row=[]
        for j in range(Wb//S):
            ok=all(a[r][c]==obj for r in range(y0+i*S,y0+(i+1)*S) for c in range(x0+j*S,x0+(j+1)*S))
            row.append(dotcol if ok else bgc)
        out.append(row)
    return out

# find S that matches each demo output shape & values
for i in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    o=G[i+' output']
    for S in range(1,13):
        try:
            p=solve(G[i+' input'],S)
            if len(p)==len(o) and len(p[0])==len(o[0]) and p==o: print(i,'MATCH',S)
        except Exception as e:
            pass
    print(i,'-> no match found with single S')

